import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './PurchaseOrders.css';

const PurchaseOrders = () => {
    const [lowStockProducts, setLowStockProducts] = useState([]);
    const [purchaseOrders, setPurchaseOrders] = useState([]);
    const [selectedItems, setSelectedItems] = useState({});
    const [loading, setLoading] = useState(true);
    const [message, setMessage] = useState({ text: '', type: '' });
    const [activeTab, setActiveTab] = useState('low-stock');

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            const [lowStockRes, ordersRes] = await Promise.all([
                axios.get('http://localhost:8080/api/stock/below-reorder'),
                axios.get('http://localhost:8080/api/purchase-orders')
            ]);
            setLowStockProducts(lowStockRes.data);
            setPurchaseOrders(ordersRes.data);
            
            // Initialize selected items with recommended quantities
            const initial = {};
            lowStockRes.data.forEach(product => {
                initial[product.id] = product.recommendedOrder || 0;
            });
            setSelectedItems(initial);
            
            setLoading(false);
        } catch (error) {
            console.error('Error fetching data:', error);
            showMessage('Error loading data', 'error');
            setLoading(false);
        }
    };

    const showMessage = (text, type) => {
        setMessage({ text, type });
        setTimeout(() => setMessage({ text: '', type: '' }), 4000);
    };

    const handleQuantityChange = (productId, value) => {
        setSelectedItems({
            ...selectedItems,
            [productId]: parseInt(value) || 0
        });
    };

    const toggleProduct = (productId) => {
        setSelectedItems({
            ...selectedItems,
            [productId]: selectedItems[productId] > 0 ? 0 : lowStockProducts.find(p => p.id === productId).recommendedOrder
        });
    };

    const generatePurchaseOrder = async () => {
        const itemsToOrder = lowStockProducts.filter(product => 
            selectedItems[product.id] > 0
        );

        if (itemsToOrder.length === 0) {
            showMessage('Please select at least one product to order', 'error');
            return;
        }

        // Group items by supplier
        const ordersBySupplier = {};
        itemsToOrder.forEach(product => {
            const supplierId = product.supplier?.id || 'no-supplier';
            if (!ordersBySupplier[supplierId]) {
                ordersBySupplier[supplierId] = {
                    supplier: product.supplier,
                    items: []
                };
            }
            ordersBySupplier[supplierId].items.push({
                product: { id: product.id },
                quantity: selectedItems[product.id],
                unitPrice: product.unitPrice
            });
        });

        try {
            // Create purchase orders for each supplier
            const promises = Object.values(ordersBySupplier).map(order => {
                const purchaseOrder = {
                    supplier: order.supplier,
                    createdDate: new Date().toISOString(),
                    status: 'CREATED',
                    items: order.items
                };
                return axios.post('http://localhost:8080/api/purchase-orders', purchaseOrder);
            });

            await Promise.all(promises);
            
            showMessage(`Successfully created ${promises.length} purchase order(s)!`, 'success');
            fetchData();
            setActiveTab('orders');
        } catch (error) {
            console.error('Error creating purchase orders:', error);
            showMessage('Error creating purchase orders', 'error');
        }
    };

    const calculateTotal = (items) => {
        return items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0).toFixed(2);
    };

    if (loading) {
        return <div className="loading">Loading purchase orders...</div>;
    }

    return (
        <div className="purchase-orders">
            <h1>Purchase Order Management</h1>

            {message.text && (
                <div className={`message ${message.type}`}>
                    {message.text}
                </div>
            )}

            <div className="tabs">
                <button 
                    className={`tab ${activeTab === 'low-stock' ? 'active' : ''}`}
                    onClick={() => setActiveTab('low-stock')}
                >
                    Low Stock Items ({lowStockProducts.length})
                </button>
                <button 
                    className={`tab ${activeTab === 'orders' ? 'active' : ''}`}
                    onClick={() => setActiveTab('orders')}
                >
                    Purchase Orders ({purchaseOrders.length})
                </button>
            </div>

            {activeTab === 'low-stock' && (
                <div className="low-stock-section">
                    {lowStockProducts.length === 0 ? (
                        <div className="no-data">
                            <div className="success-icon">✓</div>
                            <h2>All stock levels are healthy!</h2>
                            <p>No products are below their reorder point.</p>
                        </div>
                    ) : (
                        <>
                            <div className="section-header">
                                <h2>Products Below Reorder Point</h2>
                                <button 
                                    onClick={generatePurchaseOrder}
                                    className="btn-generate"
                                    disabled={Object.values(selectedItems).every(v => v === 0)}
                                >
                                    Generate Purchase Orders
                                </button>
                            </div>

                            <table className="products-table">
                                <thead>
                                    <tr>
                                        <th>Select</th>
                                        <th>SKU</th>
                                        <th>Product</th>
                                        <th>Supplier</th>
                                        <th>Current Stock</th>
                                        <th>Reorder Point</th>
                                        <th>Target Stock</th>
                                        <th>Recommended Order</th>
                                        <th>Order Quantity</th>
                                        <th>Unit Price</th>
                                        <th>Total</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {lowStockProducts.map(product => (
                                        <tr key={product.id} className={selectedItems[product.id] > 0 ? 'selected' : ''}>
                                            <td>
                                                <input
                                                    type="checkbox"
                                                    checked={selectedItems[product.id] > 0}
                                                    onChange={() => toggleProduct(product.id)}
                                                />
                                            </td>
                                            <td>{product.sku}</td>
                                            <td className="product-name">{product.name}</td>
                                            <td>{product.supplier?.name || 'No Supplier'}</td>
                                            <td>
                                                <span className="stock-critical">{product.currentStock}</span>
                                            </td>
                                            <td>{product.reorderPoint}</td>
                                            <td>{product.targetStock}</td>
                                            <td>
                                                <span className="recommended">{product.recommendedOrder}</span>
                                            </td>
                                            <td>
                                                <input
                                                    type="number"
                                                    min="0"
                                                    value={selectedItems[product.id] || 0}
                                                    onChange={(e) => handleQuantityChange(product.id, e.target.value)}
                                                    className="quantity-input"
                                                />
                                            </td>
                                            <td>${product.unitPrice?.toFixed(2)}</td>
                                            <td className="total">
                                                ${((selectedItems[product.id] || 0) * product.unitPrice).toFixed(2)}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot>
                                    <tr>
                                        <td colSpan="10" className="footer-label">Total Order Value:</td>
                                        <td className="footer-total">
                                            ${lowStockProducts.reduce((sum, p) => 
                                                sum + ((selectedItems[p.id] || 0) * p.unitPrice), 0
                                            ).toFixed(2)}
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </>
                    )}
                </div>
            )}

            {activeTab === 'orders' && (
                <div className="orders-section">
                    <h2>Purchase Orders History</h2>
                    
                    {purchaseOrders.length === 0 ? (
                        <div className="no-data">
                            <p>No purchase orders found</p>
                        </div>
                    ) : (
                        <div className="orders-list">
                            {purchaseOrders.map(order => (
                                <div key={order.id} className="order-card">
                                    <div className="order-header">
                                        <div>
                                            <h3>Order #{order.id}</h3>
                                            <p className="order-date">
                                                Created: {new Date(order.createdDate).toLocaleString()}
                                            </p>
                                        </div>
                                        <div className="order-info">
                                            <span className={`status-badge ${order.status.toLowerCase()}`}>
                                                {order.status}
                                            </span>
                                            <p className="supplier-name">
                                                {order.supplier?.name || 'No Supplier'}
                                            </p>
                                        </div>
                                    </div>
                                    
                                    <table className="order-items">
                                        <thead>
                                            <tr>
                                                <th>Product</th>
                                                <th>Quantity</th>
                                                <th>Unit Price</th>
                                                <th>Total</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {order.items?.map((item, idx) => (
                                                <tr key={idx}>
                                                    <td>{item.product?.name || `Product #${item.product?.id}`}</td>
                                                    <td>{item.quantity}</td>
                                                    <td>${item.unitPrice?.toFixed(2)}</td>
                                                    <td>${(item.quantity * item.unitPrice).toFixed(2)}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                        <tfoot>
                                            <tr>
                                                <td colSpan="3" className="footer-label">Order Total:</td>
                                                <td className="footer-total">
                                                    ${calculateTotal(order.items || [])}
                                                </td>
                                            </tr>
                                        </tfoot>
                                    </table>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default PurchaseOrders;
